export type Face = 'pix400' | 'pix600' | 'pix700' | 'plex'
/** Pixelify's "fi" ligature points at the wrong glyph ("first" drew as "Arst"): every Pixelify text turns ligatures off. */
export const NO_LIGATURES = 'font-variant-ligatures:none;font-feature-settings:"liga" 0,"clig" 0'

const rule = (family: string, weight: string, b64: string) =>
  `@font-face{font-family:"${family}";font-style:normal;font-weight:${weight};src:url(data:font/woff2;base64,${b64}) format("woff2")}`

/** The @font-face rules for the faces a step uses. The Pixelify weights share one variable file, so they come out as
 * one rule spanning the requested weights instead of repeating the data. */
export function fontFaceCss(faces: Face[]): string {
  const pix = faces.filter(f => f !== 'plex').map(f => f.slice(3)).sort()
  const out: string[] = []
  if (pix.length) out.push(rule('Pixelify Sans', pix[0] === pix[pix.length - 1] ? pix[0]! : `${pix[0]} ${pix[pix.length - 1]}`, PIXELIFY_WOFF2))
  // !important: a later `font:` shorthand resets font-variant-ligatures to normal.
  if (pix.length) out.push(`*{${NO_LIGATURES.replace(/;|$/g, '!important;')}}`)
  if (faces.includes('plex')) out.push(rule('IBM Plex Sans', '400 600', PLEX_WOFF2))
  return out.join('\n')
}
